    SeatReservation = apps.get_model("movies", "SeatReservation")
    database = schema_editor.connection.alias

    def convert_seat(seat):
        if (
            not isinstance(seat, str)
            or len(seat) < 2
            or seat[0] not in "ABCDE"
            or not seat[1:].isdigit()
        ):
            return seat
        column = int(seat[1:])
        if not 1 <= column <= 8:
            return seat
        position = (ord(seat[0]) - ord("A")) * 8 + column - 1
        if position < 30:
            return f"G{position + 1:02d}"
        if position < 80:
            return f"M{position - 29:02d}"
        return f"U{position - 79:02d}"

    for booking in SeatBooking.objects.using(database).all().iterator():
        booking.verification_token = uuid.uuid4()
        if isinstance(booking.selected_seats, list):
            booking.selected_seats = [
                convert_seat(seat) for seat in booking.selected_seats
            ]
        booking.save(
            using=database,
            update_fields=["verification_token", "selected_seats"],
        )

    for reservation in SeatReservation.objects.using(database).all().iterator():
        reservation.seat_number = convert_seat(reservation.seat_number)
        reservation.save(using=database, update_fields=["seat_number"])


